impl LspClient {
    /// Spawn `config.command` with `root` as the working directory and start the reader thread.
    pub fn spawn(config: &ServerConfig, root: &std::path::Path) -> Result<LspClient, LspError>;
    /// initialize, wait up to `timeout`, store capabilities and encoding, send initialized.
    pub fn initialize(&mut self, timeout: std::time::Duration) -> Result<(), LspError>;
    /// Write a request and return its id.
    pub fn request(&mut self, method: &'static str, params: serde_json::Value) -> Result<i64, LspError>;
    pub fn notify(&mut self, method: &str, params: serde_json::Value) -> Result<(), LspError>;
    /// Block until the response with `id` arrives or `timeout` passes. Other bodies are kept for `poll`.
    pub fn wait_for(&mut self, id: i64, timeout: std::time::Duration) -> Result<serde_json::Value, LspError>;
    /// shutdown request, exit notification, wait for the process.
    pub fn shutdown(self, timeout: std::time::Duration) -> Result<(), LspError>;
}
